package com.collectiq.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;@Entity @Table(name="invoices")public class Invoice{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;@Column(name="tenant_id",nullable=false)public String tenantId="demo";@ManyToOne(fetch=FetchType.EAGER)@JoinColumn(name="customer_id",nullable=false)public Customer customer;@Column(name="invoice_number",nullable=false)public String invoiceNumber;@Column(nullable=false,precision=14,scale=2)public BigDecimal amount;@Column(name="due_date",nullable=false)public LocalDate dueDate;@Column(nullable=false)public String status="OPEN";}